window.DPDP_DATA = {"meta":{"title":"DPDP Gap Assessor","version":"0.1.0","data_reviewed":"2026-10-29","data_reviewed_human":"29 October 2026","rule_count":13},"rules":[{"id":"R1","cite":"s.5","short":"Notice","question":"Do you give users a clear notice, in plain language, when you collect their personal data?","hint":"","answers":[{"value":"yes","label":"Yes","outcome":"ok"},{"value":"no","label":"No","outcome":"gap"},{"value":"unsure","label":"Not sure","outcome":"unsure"}],"obligation":"Give a notice that lists what personal data you collect, why, how users can exercise their rights, and how to complain to the Data Protection Board.","action":"Add a short plain-language notice at the point of collection (sign-up screen, form, app permission). Offer language options where relevant.","outcome_notes":{},"source":"DPDP Act 2023, s.5; DPDP Rules 2025 (notice rule)","phase":"Core obligations, expected May 2027","reviewed":"2026-10-29","reviewed_human":"29 October 2026"},{"id":"R2","cite":"s.6","short":"Consent for each purpose","question":"Before collecting personal data, do you ask for clear consent for each specific purpose?","hint":"","answers":[{"value":"yes","label":"Yes","outcome":"ok"},{"value":"no","label":"No","outcome":"gap"},{"value":"unsure","label":"Not sure","outcome":"unsure"}],"obligation":"Obtain free, specific, informed, unconditional and unambiguous consent through a clear affirmative action, limited to data necessary for the stated purpose.","action":"Add a consent request at the point of collection with a separate choice per purpose (for example camera, location, marketing). Do not bundle everything into one tick box.","outcome_notes":{},"source":"DPDP Act 2023, s.6","phase":"Core obligations, expected May 2027","reviewed":"2026-10-29","reviewed_human":"29 October 2026"},{"id":"R3","cite":"s.7","short":"Legitimate uses","question":"If you use personal data without consent, does the use fall under one of the 'legitimate uses' listed in the Act?","hint":"","answers":[{"value":"consent_only","label":"We rely on consent for everything","outcome":"na"},{"value":"yes","label":"Yes, each one is matched to a legitimate use and written down","outcome":"ok"},{"value":"no","label":"We use data without consent and have not matched it to a legitimate use","outcome":"gap"},{"value":"unsure","label":"Not sure","outcome":"unsure"}],"obligation":"Consent is the default. Without it, you may rely only on the specific legitimate uses listed in the Act.","action":"List every purpose where you have no consent. For each one, write down which legitimate-use ground covers it and keep that note on file.","outcome_notes":{},"source":"DPDP Act 2023, s.7","phase":"Core obligations, expected May 2027","reviewed":"2026-10-29","reviewed_human":"29 October 2026"},{"id":"R4","cite":"s.6","short":"Withdrawing consent","question":"Can users withdraw consent as easily as they gave it?","hint":"","answers":[{"value":"yes","label":"Yes","outcome":"ok"},{"value":"no","label":"No","outcome":"gap"},{"value":"unsure","label":"Not sure","outcome":"unsure"}],"obligation":"Withdrawal of consent must be as easy as giving consent, and processing must stop once consent is withdrawn (unless the law allows otherwise).","action":"Add a visible 'withdraw consent' option in settings or by email. Test it: it should take no more steps than the original sign-up.","outcome_notes":{},"source":"DPDP Act 2023, s.6","phase":"Core obligations, expected May 2027","reviewed":"2026-10-29","reviewed_human":"29 October 2026"},{"id":"R5","cite":"s.8(1)\u2013(2)","short":"Vendor contracts","question":"Do you have a written contract with each vendor that processes personal data for you (cloud, SMS, analytics, payments)?","hint":"","answers":[{"value":"yes","label":"Yes","outcome":"ok"},{"value":"no","label":"No","outcome":"gap"},{"value":"unsure","label":"Not sure","outcome":"unsure"}],"obligation":"A fiduciary may engage a processor only under a valid contract and stays responsible for compliance.","action":"List all vendors that touch user data. Sign a data processing agreement with each one covering purpose, security, deletion and breach alerts.","outcome_notes":{},"source":"DPDP Act 2023, s.8(1) and s.8(2)","phase":"Core obligations, expected May 2027","reviewed":"2026-10-29","reviewed_human":"29 October 2026"},{"id":"R6","cite":"s.8(5)","short":"Security safeguards","question":"Do you use reasonable security safeguards (access control, encryption, backups, logging) to prevent a data breach?","hint":"","answers":[{"value":"yes","label":"Yes","outcome":"ok"},{"value":"no","label":"No","outcome":"gap"},{"value":"unsure","label":"Not sure","outcome":"unsure"}],"obligation":"Protect personal data in your possession with reasonable security safeguards to prevent breach.","action":"Write down the basic safeguards you already use and the gaps. Later this row can link to ISO 27001 and Microsoft security controls.","outcome_notes":{},"source":"DPDP Act 2023, s.8(5); DPDP Rules 2025 (security safeguards rule)","phase":"Core obligations, expected May 2027","reviewed":"2026-10-29","reviewed_human":"29 October 2026"},{"id":"R7","cite":"s.8(6)","short":"Breach response","question":"Do you have a process to inform the Data Protection Board and affected users if a data breach happens?","hint":"","answers":[{"value":"yes","label":"Yes","outcome":"ok"},{"value":"no","label":"No","outcome":"gap"},{"value":"unsure","label":"Not sure","outcome":"unsure"}],"obligation":"Notify the Data Protection Board and each affected user of a personal data breach, in the form and time set by the Rules.","action":"Create a one-page incident response plan: who decides, who reports to the Board, how users are told. Check exact timelines in the Rules.","outcome_notes":{},"source":"DPDP Act 2023, s.8(6); DPDP Rules 2025 (breach intimation rule)","phase":"Core obligations, expected May 2027","reviewed":"2026-10-29","reviewed_human":"29 October 2026"},{"id":"R8","cite":"s.8(7)","short":"Erasing data","question":"Do you erase personal data when consent is withdrawn or the purpose is served, unless a law requires you to keep it?","hint":"Think about every place personal data sits: your database, email inboxes, spreadsheets and backups. Is there a set time after which it is deleted, and does anything actually do it?","answers":[{"value":"yes","label":"Yes","outcome":"ok"},{"value":"no","label":"No","outcome":"gap"},{"value":"unsure","label":"Not sure","outcome":"unsure"}],"obligation":"Erase personal data when the user withdraws consent or the purpose is no longer served, unless retention is required by law.","action":"Set a retention period for each type of data. Add a regular deletion routine and record what you delete and when.","outcome_notes":{},"source":"DPDP Act 2023, s.8(7); DPDP Rules 2025 (retention and erasure rule)","phase":"Core obligations, expected May 2027","reviewed":"2026-10-29","reviewed_human":"29 October 2026"},{"id":"R9","cite":"s.8(9)\u2013(10), s.13","short":"Contact person and grievances","question":"Do you publish contact details of a person who can answer user questions, and run a grievance process?","hint":"","answers":[{"value":"yes","label":"Yes","outcome":"ok"},{"value":"no","label":"No","outcome":"gap"},{"value":"unsure","label":"Not sure","outcome":"unsure"}],"obligation":"Publish business contact details of a person who can answer questions about processing, and provide a grievance redressal mechanism.","action":"Add a 'Privacy contact' email on your site and app, and a simple grievance form with a response-time promise.","outcome_notes":{},"source":"DPDP Act 2023, s.8(9), s.8(10) and s.13","phase":"Core obligations, expected May 2027","reviewed":"2026-10-29","reviewed_human":"29 October 2026"},{"id":"R10","cite":"s.11\u201312","short":"User requests: access, correction, erasure","question":"Can you respond to a user's request to see, correct or erase their personal data?","hint":"","answers":[{"value":"yes","label":"Yes","outcome":"ok"},{"value":"no","label":"No","outcome":"gap"},{"value":"unsure","label":"Not sure","outcome":"unsure"}],"obligation":"Give users information about their data and allow correction and erasure on request.","action":"Set up a request channel (email or form) and a log with who asked, what, and when you replied.","outcome_notes":{},"source":"DPDP Act 2023, s.11 and s.12","phase":"Core obligations, expected May 2027","reviewed":"2026-10-29","reviewed_human":"29 October 2026"},{"id":"R11","cite":"s.9","short":"Children\u2019s data","question":"Do you process data of children (under 18)? If yes, do you get verifiable parental consent?","hint":"If anyone can sign up without an age check, you may not be able to rule out users under 18. \u201cNot sure\u201d is a fair answer.","answers":[{"value":"none","label":"No, we do not process data of anyone under 18","outcome":"na"},{"value":"yes","label":"Yes, and we get verifiable parental consent","outcome":"ok"},{"value":"no","label":"Yes, but we do not get verifiable parental consent","outcome":"gap"},{"value":"unsure","label":"Not sure","outcome":"unsure"}],"obligation":"Obtain verifiable consent of a parent or lawful guardian before processing a child's data. Do not track or behaviourally monitor children or target advertising at them.","action":"Decide whether your app is open to under-18 users. If yes, add an age check and a parental consent step, and switch off tracking and targeted ads for them.","outcome_notes":{},"source":"DPDP Act 2023, s.9; DPDP Rules 2025 (children's data rule)","phase":"Core obligations, expected May 2027","reviewed":"2026-10-29","reviewed_human":"29 October 2026"},{"id":"R12","cite":"s.10","short":"Significant Data Fiduciary","question":"Has the Government notified you as a Significant Data Fiduciary?","hint":"","answers":[{"value":"not_notified","label":"No, we have not been notified","outcome":"na"},{"value":"notified","label":"Yes, we have been notified","outcome":"applies"},{"value":"unsure","label":"Not sure","outcome":"unsure"}],"obligation":"A Significant Data Fiduciary must appoint a Data Protection Officer based in India and an independent data auditor, and carry out impact assessments and periodic audits.","action":"Most early-stage startups are not notified. Mark N/A unless notified, and watch for government notifications.","outcome_notes":{"na":"Most early-stage startups are not notified. Mark N/A unless notified, and watch for government notifications.","applies":"As a notified Significant Data Fiduciary you must appoint a Data Protection Officer based in India and an independent data auditor, and carry out impact assessments and periodic audits. Plan for these now."},"source":"DPDP Act 2023, s.10","phase":"Core obligations, expected May 2027","reviewed":"2026-10-29","reviewed_human":"29 October 2026"},{"id":"R13","cite":"s.16","short":"Transfers outside India","question":"Do you transfer personal data outside India (for example foreign cloud servers or vendors)?","hint":"","answers":[{"value":"india_only","label":"No, our data stays in India","outcome":"na"},{"value":"abroad","label":"Yes, some data is stored or processed abroad","outcome":"applies"},{"value":"unsure","label":"Not sure","outcome":"unsure"}],"obligation":"Transfers are allowed except to countries the Government restricts by notification. Stricter sector rules may still apply.","action":"List where data is stored and which vendors are abroad. Check the Government's current list of restricted countries and any sector rules such as RBI for payments data.","outcome_notes":{},"source":"DPDP Act 2023, s.16","phase":"Core obligations, expected May 2027","reviewed":"2026-10-29","reviewed_human":"29 October 2026"}]};
